    # g is a list of values [g(0), g(1), ..., g(max_val)]
    # Check if g(1) == 1
    if g[1] != 1:
        return False

    # Check g(a) - g(b) | a^n - b^n for all 0 <= a, b <= max_val
    for a in range(max_val + 1):
        for b in range(a + 1, max_val + 1):
            diff_g = g[a] - g[b]
            diff_n = a**n - b**n
            if diff_g == 0:
                if diff_n != 0:
                    return False
            else:
                if diff_n % diff_g != 0:
                    return False
    return True

