from functools import reduce

def get_gcd_all(n, k):
    m = n // k
    if m == 1:
        return 1

    vals = []
    # Take some small values of a and b
    for a in range(1, 10):
        for b in range(a + 1, 10):
            val = 0
            for j in range(m):
                val += (a**(k * j)) * (b**(k * (m - 1 - j)))
            vals.append(val)

    res = vals[0]
    for v in vals[1:]:
        res = gcd(res, v)
    return res

for n in range(1, 20):
